   703→// PayloadToHeaderCapella converts `payload` into execution payload header format.
   704→func PayloadToHeaderCapella(payload interfaces.ExecutionData) (*enginev1.ExecutionPayloadHeaderCapella, error) {
   705→	txs, err := payload.Transactions()
   706→	if err != nil {
   707→		return nil, err
   708→	}
   709→	txRoot, err := ssz.TransactionsRoot(txs)
   710→	if err != nil {
   711→		return nil, err
   712→	}
   713→	withdrawals, err := payload.Withdrawals()
   714→	if err != nil {
   715→		return nil, err
   716→	}
   717→	withdrawalsRoot, err := ssz.WithdrawalSliceRoot(withdrawals, fieldparams.MaxWithdrawalsPerPayload)
   718→	if err != nil {
   719→		return nil, err
   720→	}
   721→
   722→	return &enginev1.ExecutionPayloadHeaderCapella{
   723→		ParentHash:       bytesutil.SafeCopyBytes(payload.ParentHash()),
   724→		FeeRecipient:     bytesutil.SafeCopyBytes(payload.FeeRecipient()),
   725→		StateRoot:        bytesutil.SafeCopyBytes(payload.StateRoot()),
   726→		ReceiptsRoot:     bytesutil.SafeCopyBytes(payload.ReceiptsRoot()),
   727→		LogsBloom:        bytesutil.SafeCopyBytes(payload.LogsBloom()),
   728→		PrevRandao:       bytesutil.SafeCopyBytes(payload.PrevRandao()),
   729→		BlockNumber:      payload.BlockNumber(),
   730→		GasLimit:         payload.GasLimit(),
   731→		GasUsed:          payload.GasUsed(),
   732→		Timestamp:        payload.Timestamp(),
   733→		ExtraData:        bytesutil.SafeCopyBytes(payload.ExtraData()),
   734→		BaseFeePerGas:    bytesutil.SafeCopyBytes(payload.BaseFeePerGas()),
   735→		BlockHash:        bytesutil.SafeCopyBytes(payload.BlockHash()),
   736→		TransactionsRoot: txRoot[:],
   737→		WithdrawalsRoot:  withdrawalsRoot[:],
   738→	}, nil
   739→}
