   794→// IsEmptyExecutionData checks if an execution data is empty underneath. If a single field has
   795→// a non-zero value, this function will return false.
   796→func IsEmptyExecutionData(data interfaces.ExecutionData) (bool, error) {
   797→	if data == nil {
   798→		return true, nil
   799→	}
   800→	if !bytes.Equal(data.ParentHash(), make([]byte, fieldparams.RootLength)) {
   801→		return false, nil
   802→	}
   803→	if !bytes.Equal(data.FeeRecipient(), make([]byte, fieldparams.FeeRecipientLength)) {
   804→		return false, nil
   805→	}
   806→	if !bytes.Equal(data.StateRoot(), make([]byte, fieldparams.RootLength)) {
   807→		return false, nil
   808→	}
   809→	if !bytes.Equal(data.ReceiptsRoot(), make([]byte, fieldparams.RootLength)) {
   810→		return false, nil
   811→	}
   812→	if !bytes.Equal(data.LogsBloom(), make([]byte, fieldparams.LogsBloomLength)) {
   813→		return false, nil
   814→	}
   815→	if !bytes.Equal(data.PrevRandao(), make([]byte, fieldparams.RootLength)) {
   816→		return false, nil
   817→	}
   818→	if !bytes.Equal(data.BaseFeePerGas(), make([]byte, fieldparams.RootLength)) {
   819→		return false, nil
   820→	}
   821→	if !bytes.Equal(data.BlockHash(), make([]byte, fieldparams.RootLength)) {
   822→		return false, nil
   823→	}
   824→
   825→	txs, err := data.Transactions()
   826→	switch {
   827→	case errors.Is(err, consensus_types.ErrUnsupportedField):
   828→	case err != nil:
   829→		return false, err
   830→	default:
   831→		if len(txs) != 0 {
   832→			return false, nil
   833→		}
   834→	}
   835→
   836→	if len(data.ExtraData()) != 0 {
   837→		return false, nil
   838→	}
   839→	if data.BlockNumber() != 0 {
   840→		return false, nil
   841→	}
   842→	if data.GasLimit() != 0 {
   843→		return false, nil
   844→	}
   845→	if data.GasUsed() != 0 {
   846→		return false, nil
   847→	}
   848→	if data.Timestamp() != 0 {
   849→		return false, nil
   850→	}
   851→	return true, nil
   852→}
