    28→func (s *Service) validateBlob(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    29→	receivedTime := prysmTime.Now()
    30→
    31→	if pid == s.cfg.p2p.PeerID() {
    32→		return pubsub.ValidationAccept, nil
    33→	}
    34→	if s.cfg.initialSync.Syncing() {
    35→		return pubsub.ValidationIgnore, nil
    36→	}
    37→	if msg.Topic == nil {
    38→		return pubsub.ValidationReject, p2p.ErrInvalidTopic
    39→	}
    40→	m, err := s.decodePubsubMessage(msg)
    41→	if err != nil {
    42→		log.WithError(err).Error("Failed to decode message")
    43→		return pubsub.ValidationReject, err
    44→	}
    45→
    46→	bpb, ok := m.(*eth.BlobSidecar)
    47→	if !ok {
    48→		log.WithField("message", m).Error("Message is not of type *eth.BlobSidecar")
    49→		return pubsub.ValidationReject, errWrongMessage
    50→	}
    51→	blob, err := blocks.NewROBlob(bpb)
    52→	if err != nil {
    53→		return pubsub.ValidationReject, errors.Wrap(err, "roblob conversion failure")
    54→	}
    55→	vf := s.newBlobVerifier(blob, verification.GossipBlobSidecarRequirements)
    56→
    57→	if err := vf.BlobIndexInBounds(); err != nil {
    58→		return pubsub.ValidationReject, err
    59→	}
    60→
    61→	// [REJECT] The sidecar is for the correct subnet -- i.e. compute_subnet_for_blob_sidecar(sidecar.index) == subnet_id.
    62→	want := fmt.Sprintf("blob_sidecar_%d", computeSubnetForBlobSidecar(blob.Index, blob.Slot()))
    63→	if !strings.Contains(*msg.Topic, want) {
    64→		log.WithFields(blobFields(blob)).Debug("Sidecar index does not match topic")
    65→		return pubsub.ValidationReject, fmt.Errorf("wrong topic name: %s", *msg.Topic)
    66→	}
    67→
    68→	if err := vf.NotFromFutureSlot(); err != nil {
    69→		return pubsub.ValidationIgnore, err
    70→	}
    71→
    72→	startTime, err := slots.StartTime(s.cfg.clock.GenesisTime(), blob.Slot())
    73→	if err != nil {
    74→		return pubsub.ValidationIgnore, err
    75→	}
    76→
    77→	// [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, sidecar.index) with valid header signature and sidecar inclusion proof
    78→	if s.hasSeenBlobIndex(blob.Slot(), blob.ProposerIndex(), blob.Index) {
    79→		return pubsub.ValidationIgnore, nil
    80→	}
    81→
    82→	if err := vf.SlotAboveFinalized(); err != nil {
    83→		return pubsub.ValidationIgnore, err
    84→	}
    85→
    86→	if err := vf.SidecarParentSeen(s.hasBadBlock); err != nil {
    87→		go func() {
    88→			if err := s.sendBatchRootRequest(context.Background(), [][32]byte{blob.ParentRoot()}, rand.NewGenerator()); err != nil {
    89→				log.WithError(err).WithFields(blobFields(blob)).Debug("Failed to send batch root request")
    90→			}
    91→		}()
    92→		missingParentBlobSidecarCount.Inc()
    93→		return pubsub.ValidationIgnore, err
    94→	}
    95→
    96→	if err := vf.SidecarParentValid(s.hasBadBlock); err != nil {
    97→		return pubsub.ValidationReject, err
    98→	}
    99→
   100→	if err := vf.ValidProposerSignature(ctx); err != nil {
   101→		return pubsub.ValidationReject, err
   102→	}
   103→
   104→	if err := vf.SidecarParentSlotLower(); err != nil {
   105→		return pubsub.ValidationReject, err
   106→	}
   107→
   108→	if err := vf.SidecarDescendsFromFinalized(); err != nil {
   109→		return pubsub.ValidationReject, err
   110→	}
   111→
   112→	if err := vf.SidecarInclusionProven(); err != nil {
   113→		return pubsub.ValidationReject, err
   114→	}
   115→
   116→	if err := vf.SidecarKzgProofVerified(); err != nil {
   117→		saveInvalidBlobToTemp(blob)
   118→		return pubsub.ValidationReject, err
   119→	}
   120→
   121→	if err := vf.SidecarProposerExpected(ctx); err != nil {
   122→		return pubsub.ValidationReject, err
   123→	}
   124→
   125→	fields := blobFields(blob)
   126→	sinceSlotStartTime := receivedTime.Sub(startTime)
   127→	validationTime := s.cfg.clock.Now().Sub(receivedTime)
   128→	fields["sinceSlotStartTime"] = sinceSlotStartTime
   129→	fields["validationTime"] = validationTime
   130→	log.WithFields(fields).Debug("Received blob sidecar gossip")
   131→
   132→	blobSidecarVerificationGossipSummary.Observe(float64(validationTime.Milliseconds()))
   133→	blobSidecarArrivalGossipSummary.Observe(float64(sinceSlotStartTime.Milliseconds()))
   134→
   135→	vBlobData, err := vf.VerifiedROBlob()
   136→	if err != nil {
   137→		return pubsub.ValidationReject, err
   138→	}
   139→	msg.ValidatorData = vBlobData
   140→
   141→	return pubsub.ValidationAccept, nil
   142→}
