   181→// saveInvalidBlobToTemp as a block ssz. Writes to temp directory.
   182→func saveInvalidBlobToTemp(b blocks.ROBlob) {
   183→	if !features.Get().SaveInvalidBlob {
   184→		return
   185→	}
   186→	filename := fmt.Sprintf("blob_sidecar_%#x_%d_%d.ssz", b.BlockRoot(), b.Slot(), b.Index)
   187→	fp := path.Join(os.TempDir(), filename)
   188→	log.Warnf("Writing invalid blob sidecar to disk at %s", fp)
   189→	enc, err := b.MarshalSSZ()
   190→	if err != nil {
   191→		log.WithError(err).Error("Failed to ssz encode blob sidecar")
   192→		return
   193→	}
   194→	if err := file.WriteFile(fp, enc); err != nil {
   195→		log.WithError(err).Error("Failed to write to disk")
   196→	}
   197→}
